package com.productionhouse.crm.audio.dubbing.service;
import com.productionhouse.crm.auth.api.ApiException;import com.productionhouse.crm.audio.dubbing.dto.*;import com.productionhouse.crm.audio.dubbing.entity.DubbingSession;import com.productionhouse.crm.audio.dubbing.repository.DubbingSessionRepository;import com.productionhouse.crm.audio.singer.entity.SingerProfile;import com.productionhouse.crm.audio.singer.repository.SingerProfileRepository;import com.productionhouse.crm.mediahouse.media.entity.MediaAsset;import com.productionhouse.crm.mediahouse.media.repository.MediaAssetRepository;import com.productionhouse.crm.task5.util.Task5Paging;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.*;
@Service public class DubbingSessionService{
private final DubbingSessionRepository repo;private final SingerProfileRepository singers;private final MediaAssetRepository media;public DubbingSessionService(DubbingSessionRepository repo,SingerProfileRepository singers,MediaAssetRepository media){this.repo=repo;this.singers=singers;this.media=media;}
@Transactional(readOnly=true) public Page<DubbingSessionResponse> list(String q,String status,String projectRef,Long singerId,String language,LocalDateTime from,LocalDateTime to,int page,int size,String sort,String direction){String field=Set.of("name","status","createdAt","updatedAt","scheduledAt","endsAt").contains(sort)?sort:"createdAt";Sort order=Sort.by("asc".equalsIgnoreCase(direction)?Sort.Direction.ASC:Sort.Direction.DESC,field);return Task5Paging.page(repo.findAll(order).stream().filter(e->blank(q)||contains(e.getName(),q)).filter(e->blank(status)||status.equalsIgnoreCase(e.getStatus())).filter(e->blank(projectRef)||projectRef.equals(e.getProjectRef())).filter(e->singerId==null||e.getSinger()!=null&&singerId.equals(e.getSinger().getId())).filter(e->blank(language)||language.equalsIgnoreCase(e.getLanguage())).filter(e->from==null||e.getScheduledAt()!=null&&!e.getScheduledAt().isBefore(from)).filter(e->to==null||e.getScheduledAt()!=null&&!e.getScheduledAt().isAfter(to)).map(this::response).toList(),page,size);}
@Transactional(readOnly=true) public DubbingSessionResponse get(Long id){return response(find(id));}
@Transactional public DubbingSessionResponse create(DubbingSessionRequest r){return response(save(new DubbingSession(),r));}
@Transactional public DubbingSessionResponse update(Long id,DubbingSessionRequest r){return response(save(find(id),r));}
@Transactional public void delete(Long id){repo.delete(find(id));}
private DubbingSession find(Long id){return repo.findById(id).orElseThrow(()->ApiException.notFound("Dubbing session not found."));}
private DubbingSession save(DubbingSession e,DubbingSessionRequest r){if(!r.endsAt().isAfter(r.scheduledAt()))throw ApiException.badRequest("endsAt must be after scheduledAt.");String status=r.status().trim().toUpperCase(Locale.ROOT);if(!Set.of("SCHEDULED","IN_PROGRESS","COMPLETED","CANCELLED","ON_HOLD").contains(status))throw ApiException.badRequest("Unsupported dubbing status.");SingerProfile singer=singers.findById(r.singerId()).orElseThrow(()->ApiException.badRequest("Referenced singer does not exist."));MediaAsset asset=r.mediaId()==null?null:media.findById(r.mediaId()).orElseThrow(()->ApiException.badRequest("Referenced media asset does not exist."));e.setName(r.name().trim());e.setProjectRef(clean(r.projectRef()));e.setSinger(singer);e.setMediaAsset(asset);e.setScheduledAt(r.scheduledAt());e.setEndsAt(r.endsAt());e.setStudio(r.studio().trim());e.setLanguage(r.language().trim());e.setStatus(status);e.setNotes(clean(r.notes()));e.setActive(r.active()==null||r.active());return repo.save(e);}
private DubbingSessionResponse response(DubbingSession e){return new DubbingSessionResponse(e.getId(),e.getName(),e.getProjectRef(),e.getSinger()==null?null:e.getSinger().getId(),e.getSinger()==null?null:e.getSinger().getName(),e.getMediaAsset()==null?null:e.getMediaAsset().getId(),e.getScheduledAt(),e.getEndsAt(),e.getStudio(),e.getLanguage(),e.getStatus(),e.getNotes(),e.isActive(),e.getCreatedAt(),e.getUpdatedAt());}
private boolean blank(String x){return x==null||x.isBlank();}private boolean contains(String x,String q){return x!=null&&x.toLowerCase(Locale.ROOT).contains(q.trim().toLowerCase(Locale.ROOT));}private String clean(String x){return x==null||x.isBlank()?null:x.trim();}}

